initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing an initial Entity ${entity} 
        with an id set to ${entityId} 
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Replace Entity with Response Status Code set to 204     and
        Retrieve Entity by Id with Response Body containing en entity element with id set to 'entity_id=${entity_id}' and body content set to 'expectation_filename=${expectation_filename}'
}
